"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["94399"],{99015(e){e.exports=JSON.parse('{"id":"FIN-191","slug":"cash-flow-from-investing","term":"Cash Flow from Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Cash flow from investing is the section of the cash flow statement that shows cash spent on, or received from, long-term assets and investments.","explanation":["Investing activities include buying and selling property, plant and equipment, buying and selling other businesses, and buying and selling investments such as shares and bonds of other companies.","For a growing business, cash flow from investing is usually negative, because the company is spending money on new equipment, buildings or acquisitions. For example, a company might spend 8 million on new machinery and receive 1 million from selling old vehicles, giving net cash used in investing activities of 7 million.","A negative figure is not necessarily bad. It often means the company is investing in its future. A positive figure can mean the company is selling assets, which might be a sensible clear-out of unneeded property or a sign it needs cash.","Analysts compare investing cash flows with operating cash flows. A company whose operations generate enough cash to fund its investments is in a strong position. One that must borrow or raise new equity to keep investing is more dependent on outside funding."],"note":"","total":1500,"prev":{"slug":"cash-flow-from-financing","term":"Cash Flow from Financing"},"next":{"slug":"cash-flow-statement","term":"Cash Flow Statement"}}')}}]);